#!/usr/bin/env python3
"""AXP Historical Stock Performance Report Generator"""

import pandas as pd
import numpy as np
import json
import base64
from io import BytesIO
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
import warnings
warnings.filterwarnings('ignore')

# ── 1. LOAD DATA ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], utc=True).dt.tz_convert('America/New_York')
df = df.sort_values('Date').reset_index(drop=True)
df['Year'] = df['Date'].dt.year
df['Decade'] = (df['Year'] // 10) * 10

# ── 2. KPI CALCULATIONS ───────────────────────────────────────────────────────
first_price = df['Close'].iloc[0]
last_price  = df['Close'].iloc[-1]
first_date  = df['Date'].iloc[0]
last_date   = df['Date'].iloc[-1]
years_held  = (last_date - first_date).days / 365.25

cumulative_return = (last_price / first_price - 1) * 100
cagr = ((last_price / first_price) ** (1 / years_held) - 1) * 100

# Daily returns (skip first row)
df['DailyReturn'] = df['Close'].pct_change()

# Annualized volatility (full period)
ann_vol = df['DailyReturn'].std() * np.sqrt(252) * 100

# Maximum Drawdown
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max
max_drawdown = drawdown.min() * 100
max_dd_date = df.loc[drawdown.idxmin(), 'Date']

total_dividends = df['Dividends'].sum()

# ── 3. DECADE STATS ───────────────────────────────────────────────────────────
decade_stats = []
for decade in sorted(df['Decade'].unique()):
    sub = df[df['Decade'] == decade].copy()
    if len(sub) < 2:
        continue
    label = f"{decade}s"
    start_p = sub['Close'].iloc[0]
    end_p   = sub['Close'].iloc[-1]
    n_years = (sub['Date'].iloc[-1] - sub['Date'].iloc[0]).days / 365.25
    ret     = (end_p / start_p - 1) * 100 if start_p > 0 else 0
    cagr_d  = ((end_p / start_p) ** (1 / n_years) - 1) * 100 if n_years > 0.5 and start_p > 0 else 0
    vol_d   = sub['DailyReturn'].std() * np.sqrt(252) * 100
    divs_d  = sub['Dividends'].sum()
    rm      = sub['Close'].cummax()
    dd_d    = ((sub['Close'] - rm) / rm).min() * 100
    decade_stats.append({
        'Decade': label,
        'Start Price': round(start_p, 2),
        'End Price': round(end_p, 2),
        'Total Return (%)': round(ret, 1),
        'CAGR (%)': round(cagr_d, 1),
        'Ann. Volatility (%)': round(vol_d, 1),
        'Max Drawdown (%)': round(dd_d, 1),
        'Total Dividends ($)': round(divs_d, 4),
    })

# ── 4. DRAWDOWN EPISODES ─────────────────────────────────────────────────────
# Identify notable bear episodes
episodes = [
    ('1973–1974 Oil Crisis',    '1973-01-01', '1974-12-31'),
    ('1987 Black Monday',       '1987-08-01', '1987-12-31'),
    ('2000–2002 Dot-com Bust',  '2000-01-01', '2002-12-31'),
    ('2008 Financial Crisis',   '2007-10-01', '2009-03-31'),
    ('2020 COVID-19 Crash',     '2020-01-01', '2020-06-30'),
    ('2022 Rate-Hike Selloff',  '2021-12-01', '2023-01-31'),
]
episode_rows = []
for name, s, e in episodes:
    sub = df[(df['Date'] >= s) & (df['Date'] <= e)].copy()
    if len(sub) < 5:
        continue
    peak_idx  = sub['Close'].idxmax()
    trough_idx = sub.loc[peak_idx:, 'Close'].idxmin()
    peak_p    = sub.loc[peak_idx, 'Close']
    trough_p  = sub.loc[trough_idx, 'Close']
    dd_ep     = (trough_p / peak_p - 1) * 100
    episode_rows.append({
        'Episode': name,
        'Peak Price ($)': round(peak_p, 2),
        'Trough Price ($)': round(trough_p, 2),
        'Drawdown (%)': round(dd_ep, 1),
    })

# ── 5. ANNUAL DIVIDEND SUMMARY ───────────────────────────────────────────────
annual_divs = df[df['Dividends'] > 0].groupby('Year')['Dividends'].sum().reset_index()
annual_divs.columns = ['Year', 'Total Dividends']

# ── 6. SPLIT EVENTS ───────────────────────────────────────────────────────────
splits = df[df['Stock Splits'] > 0][['Date', 'Stock Splits', 'Close']].copy()
splits['Date'] = splits['Date'].dt.strftime('%Y-%m-%d')

# ── 7. CHART HELPERS ─────────────────────────────────────────────────────────
NAVY   = '#0B1F3A'
GOLD   = '#C9A84C'
TEAL   = '#1A8C7A'
RED    = '#C0392B'
LGRAY  = '#F5F6F8'
DGRAY  = '#4A4A5A'

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.facecolor': LGRAY,
    'figure.facecolor': 'white',
    'axes.spines.top': False,
    'axes.spines.right': False,
    'axes.labelcolor': DGRAY,
    'xtick.color': DGRAY,
    'ytick.color': DGRAY,
})

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=130, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

# ── CHART 1: Full price history (log scale) ────────────────────────────────
fig, ax = plt.subplots(figsize=(13, 5))
ax.semilogy(df['Date'], df['Close'], color=NAVY, lw=1.0)
ax.fill_between(df['Date'], df['Close'], alpha=0.12, color=NAVY)
ax.set_title('AXP Closing Price – Full History (Log Scale, Adjusted)', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_xlabel('Year'); ax.set_ylabel('Price (USD, log)')
# Annotate key events
events_ann = [
    ('2009-03-09', 'GFC Trough', -40),
    ('2020-03-23', 'COVID Low', -40),
    ('2022-02-01', '2022 High', 30),
]
for d, lbl, yoff in events_ann:
    row = df[df['Date'].dt.strftime('%Y-%m-%d') == d]
    if row.empty:
        closest = df.iloc[(df['Date'] - pd.Timestamp(d, tz='America/New_York')).abs().argsort()[:1]]
        row = closest
    x_val = row['Date'].values[0]
    y_val = row['Close'].values[0]
    ax.annotate(lbl, xy=(x_val, y_val), xytext=(0, yoff),
                textcoords='offset points', fontsize=7.5,
                arrowprops=dict(arrowstyle='->', color=RED, lw=0.8),
                color=RED, ha='center')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:.0f}' if x >= 1 else f'${x:.2f}'))
ax.grid(True, which='both', alpha=0.3, ls='--')
chart1 = fig_to_b64(fig)

# ── CHART 2: Drawdown underwater chart ────────────────────────────────────
dd_series = drawdown * 100
fig, ax = plt.subplots(figsize=(13, 4))
ax.fill_between(df['Date'], dd_series, 0, color=RED, alpha=0.65)
ax.plot(df['Date'], dd_series, color=RED, lw=0.6)
ax.set_title('Drawdown from All-Time High (%)', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_xlabel('Year'); ax.set_ylabel('Drawdown (%)')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}%'))
ax.grid(True, alpha=0.3, ls='--')
chart2 = fig_to_b64(fig)

# ── CHART 3: Annual volume ─────────────────────────────────────────────────
annual_vol = df[df['Volume'] > 0].groupby('Year')['Volume'].mean() / 1e6
fig, ax = plt.subplots(figsize=(13, 4))
ax.bar(annual_vol.index, annual_vol.values, color=TEAL, alpha=0.85, width=0.8)
ax.set_title('Average Daily Trading Volume by Year (Millions of Shares)', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_xlabel('Year'); ax.set_ylabel('Avg Daily Volume (M shares)')
ax.grid(True, axis='y', alpha=0.3, ls='--')
chart3 = fig_to_b64(fig)

# ── CHART 4: Annual dividends bar ─────────────────────────────────────────
fig, ax = plt.subplots(figsize=(13, 4))
ax.bar(annual_divs['Year'], annual_divs['Total Dividends'], color=GOLD, alpha=0.9, width=0.8)
ax.set_title('Total Annual Dividends Per Share (Adjusted)', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_xlabel('Year'); ax.set_ylabel('Dividends per Share ($)')
ax.grid(True, axis='y', alpha=0.3, ls='--')
chart4 = fig_to_b64(fig)

# ── CHART 5: Decade comparison – CAGR & Volatility ────────────────────────
dec_df = pd.DataFrame(decade_stats)
x = np.arange(len(dec_df))
width = 0.38
fig, ax = plt.subplots(figsize=(11, 5))
b1 = ax.bar(x - width/2, dec_df['CAGR (%)'], width, label='CAGR (%)', color=NAVY, alpha=0.85)
b2 = ax.bar(x + width/2, dec_df['Ann. Volatility (%)'], width, label='Ann. Volatility (%)', color=GOLD, alpha=0.85)
ax.set_xticks(x); ax.set_xticklabels(dec_df['Decade'])
ax.set_title('Decade-by-Decade: CAGR vs Annualized Volatility', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_ylabel('%'); ax.legend()
ax.axhline(0, color=DGRAY, lw=0.8)
ax.grid(True, axis='y', alpha=0.3, ls='--')
for b in b1:
    h = b.get_height()
    ax.text(b.get_x() + b.get_width()/2, h + (0.3 if h >= 0 else -1.5),
            f'{h:.1f}%', ha='center', va='bottom', fontsize=7.5, color=NAVY)
chart5 = fig_to_b64(fig)

# ── CHART 6: Rolling 252-day volatility ───────────────────────────────────
roll_vol = df['DailyReturn'].rolling(252).std() * np.sqrt(252) * 100
fig, ax = plt.subplots(figsize=(13, 4))
ax.plot(df['Date'], roll_vol, color=TEAL, lw=1.0)
ax.fill_between(df['Date'], roll_vol, alpha=0.2, color=TEAL)
ax.set_title('Rolling 1-Year Annualized Volatility (%)', fontsize=13, fontweight='bold', color=NAVY, pad=10)
ax.set_xlabel('Year'); ax.set_ylabel('Volatility (%)')
ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'{x:.0f}%'))
ax.grid(True, alpha=0.3, ls='--')
chart6 = fig_to_b64(fig)

# ── 8. BUILD HTML ─────────────────────────────────────────────────────────────
def kpi_card(title, value, subtitle='', color=NAVY):
    return f"""
    <div class="kpi-card">
      <div class="kpi-title">{title}</div>
      <div class="kpi-value" style="color:{color}">{value}</div>
      <div class="kpi-sub">{subtitle}</div>
    </div>"""

def df_to_html(d, cls=''):
    return d.to_html(index=False, border=0, classes=f'data-table {cls}')

# Decade table
dec_tbl = df_to_html(dec_df)

# Episode table
ep_df = pd.DataFrame(episode_rows)
ep_tbl = df_to_html(ep_df)

# Splits table
if len(splits) > 0:
    splits_html = splits.to_html(index=False, border=0, classes='data-table')
else:
    splits_html = '<p>No stock split events recorded in the dataset.</p>'

# Annual dividend sample (recent 20)
recent_divs = annual_divs.tail(30).sort_values('Year', ascending=False)
recent_divs['Total Dividends'] = recent_divs['Total Dividends'].map(lambda x: f'${x:.4f}')
div_tbl = df_to_html(recent_divs)

max_dd_str  = f"{max_drawdown:.1f}%"
max_dd_date_str = max_dd_date.strftime('%b %Y')

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>American Express (AXP) – Historical Stock Performance Report</title>
<style>
  :root {{
    --navy: #0B1F3A;
    --gold:  #C9A84C;
    --teal:  #1A8C7A;
    --red:   #C0392B;
    --lgray: #F5F6F8;
    --dgray: #4A4A5A;
    --white: #FFFFFF;
    --border: #DEE2E6;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Segoe UI', Arial, sans-serif;
    background: var(--lgray);
    color: var(--dgray);
    font-size: 14px;
    line-height: 1.55;
  }}
  /* HEADER */
  .header {{
    background: linear-gradient(135deg, var(--navy) 60%, #1a3a6e);
    color: white;
    padding: 36px 48px 28px;
    border-bottom: 4px solid var(--gold);
  }}
  .header h1 {{ font-size: 26px; font-weight: 700; letter-spacing: 0.3px; }}
  .header .sub {{ font-size: 14px; opacity: 0.75; margin-top: 6px; }}
  .header .badge {{
    display: inline-block; background: var(--gold); color: var(--navy);
    padding: 3px 10px; border-radius: 3px; font-size: 11px; font-weight: 700;
    margin-top: 10px; letter-spacing: 0.5px;
  }}
  /* LAYOUT */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 32px 24px; }}
  .section {{
    background: white; border-radius: 8px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.07);
    margin-bottom: 28px; overflow: hidden;
  }}
  .section-header {{
    background: var(--navy); color: white;
    padding: 14px 24px; font-size: 15px; font-weight: 600;
    border-left: 5px solid var(--gold);
  }}
  .section-body {{ padding: 24px; }}
  /* KPI DASHBOARD */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 6px;
  }}
  .kpi-card {{
    background: var(--lgray);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px 16px;
    text-align: center;
  }}
  .kpi-title {{ font-size: 11px; font-weight: 600; text-transform: uppercase;
                letter-spacing: 0.7px; color: var(--dgray); margin-bottom: 8px; }}
  .kpi-value {{ font-size: 26px; font-weight: 700; line-height: 1.1; }}
  .kpi-sub   {{ font-size: 11px; color: #888; margin-top: 5px; }}
  /* TABLES */
  .data-table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  .data-table th {{
    background: var(--navy); color: white;
    padding: 10px 12px; text-align: left; font-weight: 600;
  }}
  .data-table td {{ padding: 8px 12px; border-bottom: 1px solid var(--border); }}
  .data-table tr:nth-child(even) td {{ background: var(--lgray); }}
  .data-table tr:hover td {{ background: #eaf0fb; }}
  /* CHARTS */
  .chart-wrap {{ margin: 16px 0 8px; text-align: center; }}
  .chart-wrap img {{ max-width: 100%; border-radius: 6px; }}
  /* GRID 2-COL */
  .grid2 {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  @media (max-width: 760px) {{ .grid2 {{ grid-template-columns: 1fr; }} }}
  /* INLINE HIGHLIGHT */
  .highlight {{ color: var(--teal); font-weight: 600; }}
  .neg {{ color: var(--red); font-weight: 600; }}
  p {{ margin-bottom: 10px; }}
  /* FOOTER */
  .footer {{
    text-align: center; padding: 20px; font-size: 11px;
    color: #999; border-top: 1px solid var(--border); margin-top: 12px;
  }}
  /* NAV */
  .toc {{ display: flex; gap: 10px; flex-wrap: wrap; padding: 16px 24px;
          background: white; border-bottom: 1px solid var(--border);
          position: sticky; top: 0; z-index: 50; }}
  .toc a {{
    color: var(--navy); text-decoration: none; font-size: 12px;
    font-weight: 600; padding: 4px 10px; border-radius: 4px;
    border: 1px solid var(--border); white-space: nowrap;
  }}
  .toc a:hover {{ background: var(--navy); color: white; }}
</style>
</head>
<body>

<div class="header">
  <h1>American Express (AXP) — Historical Stock Performance Report</h1>
  <div class="sub">Comprehensive analysis of 50+ years of daily trading data: June 1972 – March 2026</div>
  <span class="badge">INVESTOR GRADE · CONFIDENTIAL</span>
</div>

<nav class="toc">
  <a href="#overview">Executive Overview</a>
  <a href="#price-trend">Price Trend</a>
  <a href="#volatility">Volatility &amp; Risk</a>
  <a href="#volume">Volume</a>
  <a href="#dividends">Dividends &amp; Splits</a>
  <a href="#decades">Decade Comparison</a>
</nav>

<div class="container">

<!-- ═══════════════════════════════════════════════════════════ SECTION 1 -->
<div class="section" id="overview">
